package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"strconv"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	digits := strconv.Itoa(n)
	var memo [11][2][2][1024]int64
	for i := range memo {
		for t := range memo[i] {
			for s := range memo[i][t] {
				for m := range memo[i][t][s] {
					memo[i][t][s][m] = -1
				}
			}
		}
	}

	var dfs func(pos, tight, started, mask int) int64
	dfs = func(pos, tight, started, mask int) int64 {
		if pos == len(digits) {
			if started == 1 {
				return 1
			}
			return 0
		}

		if memo[pos][tight][started][mask] != -1 {
			return memo[pos][tight][started][mask]
		}

		limit := 9
		if tight == 1 {
			limit = int(digits[pos] - '0')
		}

		var result int64
		for d := 0; d <= limit; d++ {
			nextTight := 0
			if tight == 1 && d == limit {
				nextTight = 1
			}

			if started == 0 && d == 0 {
				result += dfs(pos+1, nextTight, 0, 0)
			} else {
				nextMask := mask | (1 << d)
				if bits.OnesCount(uint(nextMask)) <= 2 {
					result += dfs(pos+1, nextTight, 1, nextMask)
				}
			}
		}

		memo[pos][tight][started][mask] = result
		return result
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 1, 0, 0))
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n string
	fmt.Fscan(in, &n)

	length := len(n)
	memo := make([][]int64, length)
	for i := range memo {
		memo[i] = make([]int64, 1024)
		for j := range memo[i] {
			memo[i][j] = -1
		}
	}

	var dfs func(pos, mask int, tight bool) int64
	dfs = func(pos, mask int, tight bool) int64 {
		if pos == length {
			if mask != 0 {
				return 1
			}
			return 0
		}

		if !tight && memo[pos][mask] != -1 {
			return memo[pos][mask]
		}

		limit := 9
		if tight {
			limit = int(n[pos] - '0')
		}

		var result int64
		for digit := 0; digit <= limit; digit++ {
			nextTight := tight && digit == limit
			nextMask := mask

			if mask == 0 && digit == 0 {
				nextMask = 0
			} else {
				nextMask |= 1 << digit
				if nextMask&(nextMask-1) != 0 {
					withoutOne := nextMask & (nextMask - 1)
					if withoutOne&(withoutOne-1) != 0 {
						continue
					}
				}
			}

			result += dfs(pos+1, nextMask, nextTight)
		}

		if !tight {
			memo[pos][mask] = result
		}
		return result
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 0, true))
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n string
	fmt.Fscan(in, &n)

	var dp [2][2][1024]int64
	dp[1][0][0] = 1

	for _, ch := range n {
		var next [2][2][1024]int64
		limitDigit := int(ch - '0')

		for tight := 0; tight <= 1; tight++ {
			for started := 0; started <= 1; started++ {
				for mask := 0; mask < 1024; mask++ {
					count := dp[tight][started][mask]
					if count == 0 {
						continue
					}

					limit := 9
					if tight == 1 {
						limit = limitDigit
					}

					for digit := 0; digit <= limit; digit++ {
						newTight := 0
						if tight == 1 && digit == limitDigit {
							newTight = 1
						}

						if started == 0 && digit == 0 {
							next[newTight][0][0] += count
							continue
						}

						newMask := mask | (1 << digit)
						if bits.OnesCount(uint(newMask)) <= 2 {
							next[newTight][1][newMask] += count
						}
					}
				}
			}
		}

		dp = next
	}

	var answer int64
	for tight := 0; tight <= 1; tight++ {
		for mask := 0; mask < 1024; mask++ {
			answer += dp[tight][1][mask]
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

