func main() {
	in := bufio.NewReader(os.Stdin)
	var n string
	fmt.Fscan(in, &n)

	var memo [11][2][2][1024]int64
	var seen [11][2][2][1024]bool

	var dfs func(int, int, int, int) int64
	dfs = func(pos, tight, started, mask int) int64 {
		if pos == len(n) {
			if started == 1 {
				return 1
			}
			return 0
		}
		if seen[pos][tight][started][mask] {
			return memo[pos][tight][started][mask]
		}
		seen[pos][tight][started][mask] = true

		limit := 9
		if tight == 1 {
			limit = int(n[pos] - '0')
		}

		var result int64
		for digit := 0; digit <= limit; digit++ {
			nextTight := 0
			if tight == 1 && digit == limit {
				nextTight = 1
			}

			if started == 0 && digit == 0 {
				result += dfs(pos+1, nextTight, 0, 0)
				continue
			}

			nextMask := mask | (1 << digit)
			if bits.OnesCount(uint(nextMask)) <= 2 {
				result += dfs(pos+1, nextTight, 1, nextMask)
			}
		}

		memo[pos][tight][started][mask] = result
		return result
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 1, 0, 0))
