package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n string
	fmt.Fscan(in, &n)

	digits := make([]int, len(n))
	for i := range n {
		digits[i] = int(n[i] - '0')
	}

	memo := make(map[int]int64)

	var dp func(pos, mask int, started, tight bool) int64
	dp = func(pos, mask int, started, tight bool) int64 {
		if pos == len(digits) {
			if started {
				return 1
			}
			return 0
		}

		key := pos*2048 + mask*2
		if started {
			key++
		}
		if !tight {
			if value, ok := memo[key]; ok {
				return value
			}
		}

		limit := 9
		if tight {
			limit = digits[pos]
		}

		var result int64
		for digit := 0; digit <= limit; digit++ {
			nextTight := tight && digit == limit

			if !started && digit == 0 {
				result += dp(pos+1, mask, false, nextTight)
				continue
			}

			nextMask := mask | (1 << digit)
			if bits.OnesCount(uint(nextMask)) <= 2 {
				result += dp(pos+1, nextMask, true, nextTight)
			}
		}

		if !tight {
			memo[key] = result
		}
		return result
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp(0, 0, false, true))
}
